#include "nsmbudx/throws.h"

// Generated by sweet-dx from hooks/throws.hks.
extern "C" int Throws_canThrow_orig(void* player);
extern "C" int Throws_createFireBall_orig(void* player, int spin);

namespace {

nsmbudx::throws::Gate sGates[nsmbudx::throws::cMaxGates];
nsmbudx::throws::Handler sHandlers[nsmbudx::throws::cMaxHandlers];
u32 sNumGates;
u32 sNumHandlers;

} // namespace

// Player::canThrow (0x607AA954): 1 starts the throw state.
extern "C" int Throws_canThrow(void* player)
{
    int r = Throws_canThrow_orig(player);
    if (r != 1)
        return r;
    for (u32 i = 0; i < sNumGates; i++)
        if (!sGates[i](player))
            return 0;
    return r;
}

// Player::createFireBall (0x607AABA0): (player, spin). Also reached without
// canThrow (the spin-jump throw, 0x607AB2C8), so the gates apply here too.
extern "C" int Throws_createFireBall(void* player, int spin)
{
    for (u32 i = 0; i < sNumGates; i++)
        if (!sGates[i](player))
            return 0;
    for (u32 i = 0; i < sNumHandlers; i++) {
        int result = 0;
        if (sHandlers[i](player, spin, &result))
            return result;
    }
    return Throws_createFireBall_orig(player, spin);
}

namespace nsmbudx {
namespace throws {

bool addGate(Gate gate)
{
    if (!gate || sNumGates >= cMaxGates)
        return false;
    sGates[sNumGates++] = gate;
    return true;
}

bool addHandler(Handler handler)
{
    if (!handler || sNumHandlers >= cMaxHandlers)
        return false;
    sHandlers[sNumHandlers++] = handler;
    return true;
}

} // namespace throws
} // namespace nsmbudx
